mapper.select:
SELECT
    c.id AS classId,
    IFNULL(CONCAT(g.grade_name, c.class_name), c.class_name) AS className,
    IFNULL(sc.classStudentCount, 0) AS classStudentCount
FROM t_educl_class c
LEFT JOIN t_educl_grade g ON g.id = c.grade_id AND g.is_valid = 1
LEFT JOIN (
    SELECT class_id, COUNT(*) AS classStudentCount
    FROM t_as_student
    WHERE is_valid = 1
      AND school_id = #{schoolId}
      AND register_status = 1
      AND term_id = #{termId}
    GROUP BY class_id
) sc ON sc.class_id = c.id
WHERE c.is_valid = 1
  AND c.head_teacher_id = #{headTeacherId}
  AND c.school_id = #{schoolId}
  AND c.term_id = #{termId}

    AND c.id = #{classId}
